custom_qss:
/* ============================================================
   CERULEAN - deep glass theme (blue)
   Pushes Verdant further:
   - ONE gradient zone; every control is translucent glass over it
   - no solid borders anywhere; alpha hairlines only
   - chrome (menubar/toolbars/docks/statusbar) fully transparent
   - scrollbars sleep until hovered
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #d3e3f4 !important;
}

/* --- the single gradient zone: window + dialogs only --- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #16283c, stop:0.45 #0c1622, stop:1 #070d14) !important;
}
QDialog {
    background: qlineargradient(x1:0, y1:0, x2:0.12, y2:1,
        stop:0 #16283c, stop:0.45 #0c1622, stop:1 #070d14) !important;
}

/* --- menubar melts into the window --- */
QMenuBar {
    background: transparent !important;
}
QMenuBar::item {
    padding: 4px 10px;
    border-radius: 4px;
    background: transparent !important;
    color: #64789a !important;
}
QMenuBar::item:selected {
    background: rgba(56,189,248,92) !important;
    color: #d3e3f4 !important;
}

/* --- popups: solid navy card, the only hairline in the theme --- */
QMenu {
    background: #0b1220 !important;
    border: 1px solid rgba(125,211,252,54);
    border-radius: 7px;
    padding: 5px;
}
QMenu::item {
    padding: 5px 22px 5px 14px;
    border-radius: 5px;
    background: transparent !important;
    color: #d3e3f4 !important;
}
QMenu::item:selected {
    background: rgba(56,189,248,92) !important;
    color: #7dd3fc !important;
}
QMenu::item:disabled {
    color: #3d4b61 !important;
}
QMenu::separator {
    height: 1px;
    background: rgba(125,211,252,44);
    margin: 5px 8px;
}

/* --- toolbars: pure chrome, icon buttons are not boxes --- */
QToolBar {
    background: transparent !important;
    spacing: 2px;
    padding: 3px;
}
QToolBar::separator {
    background: rgba(125,211,252,44);
    width: 1px;
    margin: 5px 3px;
}
QToolBar QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 5px;
    color: #64789a !important;
}
QToolBar QToolButton:hover {
    background: rgba(125,211,252,64) !important;
    color: #d3e3f4 !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: rgba(125,211,252,92) !important;
    border-bottom: 2px solid #38bdf8;
    color: #7dd3fc !important;
}
QToolBar QToolButton:disabled {
    color: #3d4b61 !important;
}

QToolButton {
    background: transparent !important;
    padding: 4px 7px;
    border-radius: 5px;
    color: #64789a !important;
}
QToolButton:hover {
    background: rgba(125,211,252,64) !important;
    color: #d3e3f4 !important;
}
QToolButton:checked, QToolButton:pressed {
    background: rgba(125,211,252,92) !important;
    border-bottom: 2px solid #38bdf8;
    color: #7dd3fc !important;
}
QToolButton:disabled {
    color: #3d4b61 !important;
}

/* --- buttons: glass over the gradient --- */
QPushButton {
    background-color: rgba(125,211,252,54) !important;
    border-radius: 6px;
    padding: 5px 16px;
    color: #d3e3f4 !important;
}
QPushButton:hover {
    background-color: rgba(125,211,252,64) !important;
    color: #7dd3fc !important;
}
QPushButton:pressed {
    background-color: rgba(125,211,252,92) !important;
}
QPushButton:checked {
    background-color: rgba(125,211,252,92) !important;
    border-bottom: 2px solid #38bdf8;
    color: #7dd3fc !important;
}
QPushButton:default {
    border-bottom: 2px solid #38bdf8;
}
QPushButton:disabled {
    color: #3d4b61 !important;
}

/* --- inputs: glass fill, sky underline on focus --- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: rgba(125,211,252,54) !important;
    border-bottom: 2px solid rgba(125,211,252,54);
    border-radius: 5px 5px 0 0;
    padding: 4px 7px;
    color: #d3e3f4 !important;
    selection-background-color: rgba(56,189,248,92);
    selection-color: #7dd3fc;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-bottom: 2px solid #38bdf8;
    background-color: rgba(125,211,252,64) !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #3d4b61 !important;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 16px;
}

QComboBox {
    background-color: rgba(125,211,252,54) !important;
    border-bottom: 2px solid rgba(125,211,252,54);
    border-radius: 5px 5px 0 0;
    padding: 4px 7px;
    color: #d3e3f4 !important;
}
QComboBox:hover {
    border-bottom: 2px solid rgba(56,189,248,150);
}
QComboBox:focus {
    border-bottom: 2px solid #38bdf8;
}
QComboBox::drop-down {
    border: none;
    background: transparent !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: #0b1220 !important;
    border: 1px solid rgba(125,211,252,54);
    border-radius: 6px;
    padding: 4px;
    selection-background-color: rgba(56,189,248,92);
}
QComboBox:disabled {
    color: #3d4b61 !important;
}

/* --- checkboxes/radios: glass chips --- */
QCheckBox, QRadioButton {
    color: #d3e3f4 !important;
    background: transparent !important;
    padding: 2px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background: rgba(125,211,252,64) !important;
    border-radius: 4px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    background: rgba(125,211,252,92) !important;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: #38bdf8 !important;
}
QCheckBox::indicator:checked:hover, QRadioButton::indicator:checked:hover {
    background: #7dd3fc !important;
}
QCheckBox:disabled, QRadioButton:disabled {
    color: #3d4b61 !important;
}

/* --- tabs: sky underline, glass selected surface --- */
QTabBar {
    background: transparent !important;
}
QTabBar::tab {
    background: transparent !important;
    color: #64789a !important;
    padding: 6px 16px;
    border-radius: 5px 5px 0 0;
    margin: 0 1px;
}
QTabBar::tab:hover {
    color: #d3e3f4 !important;
    background: rgba(125,211,252,54) !important;
}
QTabBar::tab:selected {
    background: rgba(125,211,252,64) !important;
    color: #7dd3fc !important;
    border-bottom: 2px solid #38bdf8;
}
QTabBar::tab:disabled {
    color: #3d4b61 !important;
}
QTabBar::close-button {
    background: transparent !important;
    border: none;
    border-radius: 3px;
}
QTabBar::close-button:hover {
    background: rgba(125,211,252,92) !important;
}
QTabWidget::pane {
    border: none;
    border-top: 1px solid rgba(125,211,252,44);
    background: transparent !important;
}

/* --- docks: melted in, slim accent tick + hairline --- */
QDockWidget {
    background: transparent !important;
    border: none;
}
QDockWidget::title {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(125,211,252,44);
    border-left: 2px solid #38bdf8;
    padding: 6px 9px;
    color: #7dd3fc !important;
    font-weight: 600;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 3px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: rgba(125,211,252,64) !important;
}

/* --- group boxes: no divider at all now, sky title groups alone --- */
QGroupBox {
    background: transparent !important;
    border: none;
    margin-top: 14px;
    padding-top: 4px;
    font-weight: 600;
    color: #d3e3f4 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 6px;
    background: transparent !important;
    color: #38bdf8 !important;
}

/* --- item views: glass lists over the gradient --- */
QAbstractItemView {
    background: rgba(125,211,252,54) !important;
    border: none;
    border-radius: 6px;
    alternate-background-color: rgba(125,211,252,18);
    selection-background-color: rgba(56,189,248,92);
    selection-color: #7dd3fc;
    outline: none;
}
QAbstractItemView::item {
    padding: 3px;
}
QAbstractItemView::item:hover {
    background: rgba(125,211,252,64) !important;
}
QAbstractItemView::item:selected {
    background: rgba(56,189,248,92) !important;
    color: #7dd3fc !important;
}
QTreeView::item, QTreeWidget::item, QTreeWidgetItem,
QTableView::item, QListView::item, QListWidget::item {
    background: transparent !important;
}

QHeaderView {
    background: transparent !important;
    border: none;
}
QHeaderView::section {
    background: transparent !important;
    border: none;
    border-bottom: 1px solid rgba(125,211,252,44);
    padding: 5px 7px;
    color: #64789a !important;
    font-weight: 600;
}
QHeaderView::section:hover {
    color: #d3e3f4 !important;
}

/* --- scrollbars: sleep until hovered --- */
QScrollBar:vertical {
    background: transparent !important;
    width: 10px;
    margin: 2px;
}
QScrollBar::handle:vertical {
    background: rgba(125,211,252,80);
    border-radius: 4px;
    min-height: 28px;
}
QScrollBar::handle:vertical:hover {
    background: rgba(56,189,248,190);
}
QScrollBar::handle:vertical:pressed {
    background: #38bdf8;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: transparent !important;
}
QScrollBar:horizontal {
    background: transparent !important;
    height: 10px;
    margin: 2px;
}
QScrollBar::handle:horizontal {
    background: rgba(125,211,252,80);
    border-radius: 4px;
    min-width: 28px;
}
QScrollBar::handle:horizontal:hover {
    background: rgba(56,189,248,190);
}
QScrollBar::handle:horizontal:pressed {
    background: #38bdf8;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: transparent !important;
}
QScrollBar::corner {
    background: transparent !important;
}

/* --- sliders: hairline track, sky fill, ice knob --- */
QSlider::groove:horizontal {
    background: rgba(125,211,252,30) !important;
    height: 3px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: #38bdf8 !important;
    border-radius: 2px;
}
QSlider::add-page:horizontal {
    background: rgba(125,211,252,30) !important;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #e0f2fe !important;
    width: 11px;
    margin: -5px 0;
    border-radius: 6px;
}
QSlider::handle:horizontal:hover {
    background: #7dd3fc !important;
}
QSlider::groove:vertical {
    background: rgba(125,211,252,30) !important;
    width: 3px;
    border-radius: 2px;
}
QSlider::sub-page:vertical {
    background: #38bdf8 !important;
    border-radius: 2px;
}
QSlider::add-page:vertical {
    background: rgba(125,211,252,30) !important;
    border-radius: 2px;
}
QSlider::handle:vertical {
    background: #e0f2fe !important;
    height: 11px;
    margin: 0 -5px;
    border-radius: 6px;
}
QSlider::handle:vertical:hover {
    background: #7dd3fc !important;
}

/* --- progress: the only moving shine --- */
QProgressBar {
    background: rgba(125,211,252,54) !important;
    border-radius: 5px;
    text-align: center;
    color: #d3e3f4 !important;
    min-height: 14px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #0ea5e9, stop:1 #38bdf8) !important;
    border-radius: 5px;
}

/* --- statusbar melts away --- */
QStatusBar {
    background: transparent !important;
    border: none;
    border-top: 1px solid rgba(125,211,252,44);
    color: #64789a !important;
}
QStatusBar::item {
    background: transparent !important;
}

/* --- tooltip: floating navy card --- */
QToolTip {
    background: #0c1524 !important;
    border: 1px solid rgba(56,189,248,90);
    border-radius: 6px;
    padding: 5px 8px;
    color: #d3e3f4 !important;
}

/* --- splitters: invisible until hovered --- */
QSplitter {
    background: transparent !important;
    border: none;
}
QSplitter::handle {
    background: transparent !important;
}
QSplitter::handle:hover {
    background: rgba(125,211,252,64) !important;
}

/* --- everything else is glass over the gradient --- */
QAbstractScrollArea {
    background: transparent !important;
    border: none;
}
QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
}
